package cn.iocoder.yudao.module.amazon.controller.admin.catalogitems;
import cn.iocoder.yudao.framework.common.pojo.CommonResult; import cn.iocoder.yudao.module.amazon.controller.admin.products.vo.AmazonProductsReqVO; import cn.iocoder.yudao.module.amazon.service.catalogitems.AmazonCatalogItemsService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.annotation.Resource; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.Map;
/** Amazon Catalog Items 管理接口。 */
@Tag(name="管理后台 - Amazon Catalog Items") @RestController @RequestMapping("/amazon/catalog-items") public class AmazonCatalogItemsController { @Resource private AmazonCatalogItemsService service; @PostMapping("/search") @Operation(summary="搜索 Amazon Catalog Items") @PreAuthorize("@ss.hasPermission('amazon:catalog-items:query')") public CommonResult<Map<String,Object>> search(@Valid @RequestBody AmazonProductsReqVO r){return CommonResult.success(service.search(r));} @PostMapping("/get") @Operation(summary="查询 Amazon Catalog Item") @PreAuthorize("@ss.hasPermission('amazon:catalog-items:query')") public CommonResult<Map<String,Object>> get(@Valid @RequestBody AmazonProductsReqVO r){return CommonResult.success(service.get(r));} }
